/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

const { fontFamily } = loadFont();



export type CompoundInterestTableProps = Record<string, any>;

const CompoundInterestTable: React.FC<CompoundInterestTableProps> = ({
  titleText = "Compound Interest Table",
  baseAmount = 10000000,
  growthRate = 15,
  totalYears = 30,
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  gridColor = "rgba(255, 255, 255, 0.15)",
  textColor = "#ffffff",
  highlightColor = "#ffffff",
  durationInSeconds = 8,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Constants
  const ROW_HEIGHT = 70;
  const HEADER_HEIGHT = 70;
  const TITLE_AREA_HEIGHT = 160;
  const TABLE_WIDTH = 1200;

  // Data Generation
  const rowsData = useMemo(() => {
    return Array.from({ length: totalYears + 1 }).map((_, i) => ({
      year: i,
      amount: baseAmount * Math.pow(1 + growthRate / 100, i),
      rate: growthRate,
    }));
  }, [baseAmount, growthRate, totalYears]);

  // Scene 1: Entrance & Odometer Animation
  const titleOpacity = interpolate(frame, [0, 20], [0, 1], { extrapolateRight: "clamp" });
  const titleY = interpolate(frame, [0, 20], [40, 0], { 
    extrapolateRight: "clamp", 
    easing: Easing.out(Easing.exp) 
  });
  
  const tableOpacity = interpolate(frame, [10, 30], [0, 1], { extrapolateRight: "clamp" });
  
  const numberProgress = interpolate(frame, [30, 90], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Scene 2: Scroll Down to Final Row
  const initialY = (height - (TITLE_AREA_HEIGHT + HEADER_HEIGHT + 6 * ROW_HEIGHT)) / 2;
  const lastRowCenterOffset = TITLE_AREA_HEIGHT + HEADER_HEIGHT + (totalYears * ROW_HEIGHT) + (ROW_HEIGHT / 2);
  const finalY = (height / 2) - lastRowCenterOffset;

  const scrollProgress = interpolate(frame, [110, 170], [0, 1], {
    easing: Easing.inOut(Easing.exp),
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const currentY = interpolate(scrollProgress, [0, 1], [initialY, finalY]);

  // Formatting utilities
  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 0,
    }).format(val);
  };

  const formatPercent = (val: number) => {
    return Math.floor(val) + "%";
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily, transition: "none" }}>
      {/* Background Grid Pattern */}
      <div style={{
        position: 'absolute',
        inset: 0,
        backgroundImage: `
          linear-gradient(to right, ${gridColor} 1px, transparent 1px),
          linear-gradient(to bottom, ${gridColor} 1px, transparent 1px)
        `,
        backgroundSize: '100px 100px',
        opacity: 0.3,
      }} />
      {/* Background Radial Vignette */}
      <div style={{
        position: 'absolute',
        inset: 0,
        background: `radial-gradient(circle at center, transparent 0%, ${bgColor} 80%)`,
        zIndex: 0,
      }} />

      {/* Main Content Wrapper - Animates Vertically */}
      <div style={{
        position: 'absolute',
        top: currentY,
        left: (width - TABLE_WIDTH) / 2,
        width: TABLE_WIDTH,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        opacity: tableOpacity,
        zIndex: 1,
      }}>
        
        {/* Title */}
        <div style={{
          height: TITLE_AREA_HEIGHT,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          opacity: titleOpacity,
          transform: `translateY(${titleY}px)`,
        }}>
          <h1 style={{
            fontSize: 64,
            fontWeight: 700,
            color: textColor,
            margin: 0,
            textShadow: `0 4px 12px rgba(0,0,0,0.5)`,
          }}>
            {titleText}
          </h1>
        </div>

        {/* Table Structure */}
        <div style={{
          width: '100%',
          borderLeft: `1px solid ${gridColor}`,
          borderRight: `1px solid ${gridColor}`,
          borderTop: `1px solid ${gridColor}`,
          backgroundColor: 'rgba(0, 0, 0, 0.4)',
          backdropFilter: 'blur(10px)',
        }}>
          {/* Header Row */}
          <div style={{
            display: 'flex',
            flexDirection: 'row',
            height: HEADER_HEIGHT,
            borderBottom: `2px solid ${gridColor}`,
            backgroundColor: 'rgba(255, 255, 255, 0.05)',
          }}>
            {['Year', 'My Money', 'Growth Rate'].map((headerText, i) => (
              <div key={headerText} style={{
                flex: 1,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: 28,
                fontWeight: 600,
                color: 'rgba(255, 255, 255, 0.7)',
                borderRight: i < 2 ? `1px solid ${gridColor}` : 'none',
              }}>
                {headerText}
              </div>
            ))}
          </div>

          {/* Body Rows */}
          {rowsData.map((row, i) => {
            // Cascading fade-in (capped at 10 to avoid excessive off-screen calculation time delays)
            const rowOpacity = interpolate(
              frame,
              [10 + Math.min(i, 10) * 3, 25 + Math.min(i, 10) * 3],
              [0, 1],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            );

            // Odometer values
            const displayYear = Math.floor(numberProgress * row.year);
            const displayAmount = numberProgress * row.amount;
            const displayRate = numberProgress * row.rate;

            const isLastRow = i === totalYears;
            
            // Highlight Animation (Triggered at bottom of scroll)
            const rowGlowOpacity = isLastRow 
              ? interpolate(frame, [170, 180], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) 
              : 0;
            
            const pulseAmplitude = 0.3 * Math.sin(Math.max(0, frame - 180) * 0.15);
            const glowSpread = rowGlowOpacity * (20 + pulseAmplitude * 10);
            
            const rowBoxShadow = isLastRow && rowGlowOpacity > 0
              ? `0 0 ${glowSpread}px ${highlightColor}, inset 0 0 ${glowSpread}px ${highlightColor}`
              : 'none';
              
            const cellTextColor = isLastRow && rowGlowOpacity > 0 ? highlightColor : textColor;
            const textShadow = isLastRow && rowGlowOpacity > 0 ? `0 0 12px ${highlightColor}` : 'none';

            return (
              <div key={i} style={{
                display: 'flex',
                flexDirection: 'row',
                height: ROW_HEIGHT,
                borderBottom: `1px solid ${gridColor}`,
                opacity: rowOpacity,
                position: isLastRow ? 'relative' : 'static',
                zIndex: isLastRow ? 10 : 1,
                boxShadow: rowBoxShadow,
                outline: isLastRow && rowGlowOpacity > 0 ? `2px solid ${highlightColor}` : 'none',
                outlineOffset: -1,
                backgroundColor: isLastRow ? `rgba(255, 255, 255, ${rowGlowOpacity * 0.15})` : 'transparent',
              }}>
                {/* Year Column */}
                <div style={{
                  flex: 1,
                  borderRight: `1px solid ${gridColor}`,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: cellTextColor,
                  textShadow,
                  fontSize: 32,
                  fontWeight: isLastRow ? 600 : 400,
                  fontVariantNumeric: 'tabular-nums',
                }}>
                  {displayYear}
                </div>
                {/* Amount Column */}
                <div style={{
                  flex: 1,
                  borderRight: `1px solid ${gridColor}`,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: cellTextColor,
                  textShadow,
                  fontSize: 32,
                  fontWeight: isLastRow ? 600 : 400,
                  fontVariantNumeric: 'tabular-nums',
                }}>
                  {formatCurrency(displayAmount)}
                </div>
                {/* Rate Column */}
                <div style={{
                  flex: 1,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: cellTextColor,
                  textShadow,
                  fontSize: 32,
                  fontWeight: isLastRow ? 600 : 400,
                  fontVariantNumeric: 'tabular-nums',
                }}>
                  {formatPercent(displayRate)}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CompoundInterestTable;